a) $\sqrt{250} \quad\quad$  b) $\sqrt{27 x}$ với $x>0 \quad\quad$  c) $\sqrt{25.\sqrt2+125} \quad\quad$   d) $\sqrt{125.\sqrt{3}-20 }$ 
\loigiai{
a) $\sqrt{250} = 5 \sqrt{10}$.\\
b) $\sqrt{27 x} = 3 \sqrt{3} \sqrt{x}$.\\
c) $\sqrt{25.\sqrt2+125} = 5 \sqrt{\sqrt{2} + 5}$.\\
d) $\sqrt{125.\sqrt{3}-20 } = \sqrt{-20 + 125 \sqrt{3}}$.
}\end{ex}

\begin{ex}%[9D3N3-1]
Đưa thừa số ra ngoài dấu căn

a) $\sqrt{27} \quad\quad$  b) $\sqrt{64 x}$ với $x>0 \quad\quad$  c) $\sqrt{4.\sqrt4+20} \quad\quad$   d) $\sqrt{100.\sqrt{5}-20 }$ 
\loigiai{
a) $\sqrt{27} = 3 \sqrt{3}$.\\
b) $\sqrt{64 x} = 8 \sqrt{x}$.\\
c) $\sqrt{4.\sqrt4+20} = 2 \sqrt{7}$.\\
d) $\sqrt{100.\sqrt{5}-20 } = 2 \sqrt{-5 + 25 \sqrt{5}}$.
}\end{ex}

\begin{ex}%[9D3N3-1]
Đưa thừa số ra ngoài dấu căn

a) $\sqrt{90} \quad\quad$  b) $\sqrt{8 x}$ với $x>0 \quad\quad$  c) $\sqrt{9.\sqrt5+36} \quad\quad$   d) $\sqrt{125.\sqrt{2}-30 }$ 
\loigiai{
a) $\sqrt{90} = 3 \sqrt{10}$.\\
b) $\sqrt{8 x} = 2 \sqrt{2} \sqrt{x}$.\\
c) $\sqrt{9.\sqrt5+36} = 3 \sqrt{\sqrt{5} + 4}$.\\
d) $\sqrt{125.\sqrt{2}-30 } = \sqrt{-30 + 125 \sqrt{2}}$.
}\end{ex}

